interface Iterator {
    open()        // initialise state, recurse open() to children
    next() → Row  // return next row; return EOF when exhausted
    close()       // release resources, recurse close() to children
}

interface VectorIterator {
    open()
    next(batchSize: Int) → ColumnBatch  // returns up to N rows
    close()
}

// ColumnBatch for a scan of (id INT, amount FLOAT):
//   ids:     [ 1,  2,  3, ... , 1000 ]   // contiguous int array
//   amounts: [ 9.5, 4.0, 12.1, ... ]      // contiguous float array
//   len: 1000

// Vectorised filter: WHERE amount > 10.0
for i in 0..batch.len:
    selection[i] = (batch.amounts[i] > 10.0)  // branch-free comparison
batch.applySelection(selection)

// Filter (σ predicate)
Filter.next():
    loop:
        row = child.next()
        if row == EOF: return EOF
        if evaluate(predicate, row): return row
        // else: discard and continue

// Project (π column_list)
Project.next():
    row = child.next()
    if row == EOF: return EOF
    return row.extract(column_list)

Phase 1 — Build:
  for row in inner_relation (smaller):
    bucket = hash(row.join_key) % num_buckets
    hash_table[bucket].append(row)

Phase 2 — Probe:
  for row in outer_relation (larger):
    bucket = hash(row.join_key) % num_buckets
    for candidate in hash_table[bucket]:
      if candidate.join_key == row.join_key:
        emit (row, candidate)   // match found

Complexity: O(|inner|) build + O(|outer|) probe
Memory:     O(|inner|) — the hash table

// Basic Nested Loop Join
for outer_row in outer_relation:
    for inner_row in inner_relation:
        if predicate(outer_row, inner_row):
            emit(outer_row, inner_row)

// Cost: O(|outer| × |inner|) — quadratic

// Index Nested Loop Join
for outer_row in outer_relation:
    for inner_row in index_lookup(inner_relation, outer_row.key):
        emit(outer_row, inner_row)

// Cost: O(|outer| × log|inner|) — log-linear when index is selective
